    'federation_welcome_step_list_body_manual' => 'Войдите на :host, откройте расписание, нажмите «:edit», затем «:schedule_settings», затем «:advanced», установите для параметра «:setting» значение «:option» и сохраните изменения. Повторите это для каждого расписания, которым хотите поделиться.',
